//! The independent oracle: every PDF we write is checked by `qpdf`.
//!
//! ## Why this exists in this shape
//!
//! A writer verified only by reading its own output back proves nothing. If our
//! notion of where the xref table goes is wrong, our reader would look in the
//! same wrong place and agree. This repository has been bitten by exactly that
//! three times — a zstd encoder that agreed perfectly with its own decoder
//! while neither could read a real file, an emitted Vite project asserted as
//! text and never built, and Anki fixtures generated by the very code they were
//! testing.
//!
//! `qpdf` is a separate implementation by people who were not us. `qpdf --check`
//! parses the file, walks the cross-reference table, follows every object
//! reference, and verifies stream lengths. That is precisely the set of
//! properties this layer is responsible for.
//!
//! ## Absence is a failure, not a skip
//!
//! [`require_qpdf`] **panics** when `qpdf` is missing. The tempting alternative
//! — return early and let the test pass — produces a suite that reports success
//! while checking nothing, which is how a missing feature can survive behind a
//! green checkmark for months. A skipped oracle is not a degraded test; it is
//! no test.

use std::io::Write as _;
use std::process::Command;

/// Find `needle` in `hay`.
///
/// These tests never build a `String` from PDF bytes: the binary marker on line
/// two is deliberately not valid UTF-8, so `from_utf8` fails, and
/// `from_utf8_lossy` would substitute a three-byte replacement character and
/// shift exactly the offsets under test.
fn find(hay: &[u8], needle: &[u8]) -> Option<usize> {
    hay.windows(needle.len()).position(|w| w == needle)
}

use pdf::{dict, Object, PdfWriter};

/// Locate `qpdf`, or fail loudly with instructions.
fn require_qpdf() -> &'static str {
    let found = Command::new("qpdf")
        .arg("--version")
        .output()
        .map(|o| o.status.success())
        .unwrap_or(false);
    assert!(
        found,
        "`qpdf` is required: it is the independent oracle for this crate, and \
         without it these tests would only prove that we can read back our own \
         bytes. Install it with `brew install qpdf` (macOS) or \
         `apt-get install qpdf` (Debian/Ubuntu)."
    );
    "qpdf"
}

/// Run `qpdf --check` over `bytes`, returning its combined output on failure.
fn qpdf_check(bytes: &[u8], label: &str) -> Result<String, String> {
    let qpdf = require_qpdf();
    let dir = std::env::temp_dir().join(format!("pdf-gate-{label}-{}", std::process::id()));
    std::fs::create_dir_all(&dir).unwrap();
    let path = dir.join("out.pdf");
    let mut file = std::fs::File::create(&path).unwrap();
    file.write_all(bytes).unwrap();
    drop(file);

    let output = Command::new(qpdf)
        .arg("--check")
        .arg(&path)
        .output()
        .expect("failed to run qpdf");
    let combined = format!(
        "{}{}",
        String::from_utf8_lossy(&output.stdout),
        String::from_utf8_lossy(&output.stderr)
    );
    let _ = std::fs::remove_dir_all(&dir);

    if output.status.success() {
        Ok(combined)
    } else {
        Err(combined)
    }
}

/// The smallest structurally complete document: catalog → pages → one page.
fn one_page_document() -> Vec<u8> {
    let mut w = PdfWriter::new();
    let pages = w.reserve();
    let page = w.add(Object::Dict(dict! {
        "Type"     => Object::name("Page"),
        "Parent"   => Object::Ref(pages),
        "MediaBox" => Object::Array(vec![
            Object::Int(0), Object::Int(0), Object::Int(612), Object::Int(792),
        ]),
        "Resources" => Object::Dict(dict! {}),
    }));
    w.fill(
        pages,
        Object::Dict(dict! {
            "Type"  => Object::name("Pages"),
            "Kids"  => Object::Array(vec![Object::Ref(page)]),
            "Count" => Object::Int(1),
        }),
    );
    let root = w.add(Object::Dict(dict! {
        "Type"  => Object::name("Catalog"),
        "Pages" => Object::Ref(pages),
    }));
    w.finish(root).unwrap()
}

#[test]
fn a_minimal_document_passes_qpdf_check() {
    let bytes = one_page_document();
    match qpdf_check(&bytes, "minimal") {
        Ok(report) => assert!(
            report.contains("No syntax or stream encoding errors"),
            "qpdf accepted the file but did not report it clean:\n{report}"
        ),
        Err(report) => panic!("qpdf rejected our minimal document:\n{report}"),
    }
}

#[test]
fn a_document_with_a_flate_stream_passes_qpdf_check() {
    // Streams are where `/Length` correctness and filter declaration matter,
    // and qpdf verifies both — it decodes the stream rather than trusting us.
    let mut w = PdfWriter::new();
    let content = b"BT /F1 24 Tf 72 720 Td (from scratch) Tj ET".repeat(20);
    let (encoded, filter) = pdf::flate_encode(&content);
    let stream = w.add(Object::Stream {
        dict: dict! { "Filter" => filter },
        data: encoded,
    });
    let pages = w.reserve();
    let page = w.add(Object::Dict(dict! {
        "Type"      => Object::name("Page"),
        "Parent"    => Object::Ref(pages),
        "MediaBox"  => Object::Array(vec![
            Object::Int(0), Object::Int(0), Object::Int(612), Object::Int(792),
        ]),
        "Contents"  => Object::Ref(stream),
        "Resources" => Object::Dict(dict! {}),
    }));
    w.fill(
        pages,
        Object::Dict(dict! {
            "Type"  => Object::name("Pages"),
            "Kids"  => Object::Array(vec![Object::Ref(page)]),
            "Count" => Object::Int(1),
        }),
    );
    let root = w.add(Object::Dict(dict! {
        "Type"  => Object::name("Catalog"),
        "Pages" => Object::Ref(pages),
    }));
    let bytes = w.finish(root).unwrap();

    if let Err(report) = qpdf_check(&bytes, "flate") {
        panic!("qpdf rejected a document with a FlateDecode stream:\n{report}");
    }
}

#[test]
fn qpdf_rejects_a_file_whose_xref_offsets_are_wrong() {
    // Proves the gate is load-bearing rather than decorative: if qpdf accepted
    // this, it would not be checking the property the whole layer exists to
    // guarantee, and every other test here would be worthless.
    let bytes = one_page_document();
    let table = find(&bytes, b"xref\n").expect("xref table") + 5;
    let after_subsection = table + find(&bytes[table..], b"\n").unwrap() + 1;
    // Entry 0 is the free-list head; corrupt the first real object's offset.
    let first = after_subsection + 20;

    let mut corrupted = bytes.clone();
    corrupted[first..first + 10].copy_from_slice(b"0000000999");

    let report = qpdf_check(&corrupted, "corrupt");
    // qpdf can reconstruct a damaged xref rather than refusing outright, so
    // accept either a hard failure or an explicit complaint. What must not
    // happen is a silent clean bill of health.
    let complained = match &report {
        Err(_) => true,
        Ok(text) => text.contains("WARNING") || text.contains("error") || text.contains("damaged"),
    };
    assert!(
        complained,
        "qpdf reported a wrong xref offset as clean, so it is not verifying \
         the property this crate is responsible for:\n{report:?}"
    );
}

#[test]
fn qpdf_rejects_a_stream_whose_declared_length_is_wrong() {
    // The other half of the same argument. Our writer derives /Length from the
    // data so it cannot produce this, which is exactly why the gate must be
    // shown to catch it -- otherwise that safeguard is untested.
    let mut w = PdfWriter::new();
    let (encoded, filter) = pdf::flate_encode(b"12345");
    let stream = w.add(Object::Stream {
        dict: dict! { "Filter" => filter },
        data: encoded,
    });
    let pages = w.reserve();
    let page = w.add(Object::Dict(dict! {
        "Type"      => Object::name("Page"),
        "Parent"    => Object::Ref(pages),
        "MediaBox"  => Object::Array(vec![
            Object::Int(0), Object::Int(0), Object::Int(612), Object::Int(792),
        ]),
        "Contents"  => Object::Ref(stream),
        "Resources" => Object::Dict(dict! {}),
    }));
    w.fill(pages, Object::Dict(dict! {
        "Type"  => Object::name("Pages"),
        "Kids"  => Object::Array(vec![Object::Ref(page)]),
        "Count" => Object::Int(1),
    }));
    let root = w.add(Object::Dict(dict! {
        "Type"  => Object::name("Catalog"),
        "Pages" => Object::Ref(pages),
    }));
    let good = w.finish(root).unwrap();

    // Shorten the declared length so it no longer matches the stream bytes.
    let marker = find(&good, b"/Length ").expect("a stream length") + 8;
    let end = marker + find(&good[marker..], b" ").unwrap();
    let mut corrupted = Vec::new();
    corrupted.extend_from_slice(&good[..marker]);
    corrupted.extend_from_slice(b"2");
    corrupted.extend_from_slice(&good[end..]);

    let report = qpdf_check(&corrupted, "badlen");
    let complained = match &report {
        Err(_) => true,
        Ok(text) => text.contains("WARNING") || text.contains("error"),
    };
    assert!(
        complained,
        "qpdf reported a stream whose /Length disagreed with its data as \
         clean:\n{report:?}"
    );
}
